&lt;h2&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;Introduction&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:280,&amp;quot;335559739&amp;quot;:60,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h2&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;We are proud of the work we do in National Security and the difference it makes to the safety and prosperity of the UK. We are looking for an experienced business developer / account manager to join our &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;thriving &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;Defence and Security Business Unit and grow our National Security business — bringing established sector experience, a strong network of contacts, and a track record of building trusted client relationships that turn into repeat business&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt; and deliver real impact&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Body Text&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;Main purpose of the job&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As Senior Business Developer / Account Manager, you will join an established commercial team working with clients across the National Security community. You will own and grow an area of our National Security business, using your existing relationships and sector knowledge to identify opportunities, shape work programmes and develop the commercial approach to bids, working on your own initiative to build your own line of business. Key client relationships and repeat business built on trust are the cornerstone of our commercial approach, and your responsibilities will include client management during project delivery.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This role is based in Cheltenham, with occasional travel to our Cambridge office.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;Responsibilities&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Wingdings&quot; data-listid=&quot;9&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:1676984,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:227,&amp;quot;335559991&amp;quot;:227,&amp;quot;469769226&amp;quot;:&amp;quot;Wingdings&amp;quot;,&amp;quot;469769242&amp;quot;:[9642],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot; data-ccp-parastyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;8a406850-9b17-55ce-ab24-1372176eb26f|1&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469775450,&amp;quot;Table Bullet&amp;quot;,201340122,&amp;quot;2&amp;quot;,134234082,&amp;quot;true&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;TableBullet&amp;quot;,335572020,&amp;quot;12&amp;quot;,201342448,&amp;quot;1&amp;quot;,469777843,&amp;quot;Arial&amp;quot;,201341986,&amp;quot;1&amp;quot;,268442635,&amp;quot;18&amp;quot;,335559705,&amp;quot;1033&amp;quot;,335559682,&amp;quot;9&amp;quot;,335559683,&amp;quot;0&amp;quot;,201342446,&amp;quot;1&amp;quot;,201342447,&amp;quot;5&amp;quot;,201342449,&amp;quot;1&amp;quot;,469777841,&amp;quot;Arial&amp;quot;,469777842,&amp;quot;Arial&amp;quot;,469777844,&amp;quot;Arial&amp;quot;,469769226,&amp;quot;Arial,微軟正黑體&amp;quot;,469777804,&amp;quot;&amp;quot;,469777803,&amp;quot;left&amp;quot;,469777815,&amp;quot;multilevel&amp;quot;,469769242,&amp;quot;9642&amp;quot;,335559685,&amp;quot;227&amp;quot;,335559991,&amp;quot;227&amp;quot;,536884268,&amp;quot;{8a406850-9b17-55ce-ab24-1372176eb26f}{1}&amp;quot;]}&quot;&gt;Develop and own &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt;y&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt;our plan for growing business within &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt;a&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt; National Security &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Table Bullet&quot;&gt;account&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
